namespace Airudit.MdBook.UnitTests;

using Airudit.MdBook.Core;
using System.Text;

/// <summary>
/// Output-destination behaviour (issue #9): the in-place side-by-side HTML files, the
/// <c>--single-file</c> bundle and the <c>--export</c> copies, and how <c>--side</c> gates them.
/// </summary>
public class OutputModeTests
{
    // --- --side flag logic, exercised through the real CLI parse task ---

    [Fact]
    public void Side_by_side_is_on_by_default_with_no_output_destination()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var layer = ParseArgs(dir.Root);
        Assert.True(layer.SideBySide);
    }

    [Fact]
    public void Single_file_suppresses_side_by_side()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var layer = ParseArgs(dir.Root, "--single-file", Path.Combine(dir.Root, "all.html"));
        Assert.False(layer.SideBySide);
    }

    [Fact]
    public void Export_suppresses_side_by_side()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var layer = ParseArgs(dir.Root, "--export", Path.Combine(dir.Root, "out"));
        Assert.False(layer.SideBySide);
    }

    [Fact]
    public void Side_flag_forces_side_by_side_alongside_single_file()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var layer = ParseArgs(dir.Root, "--single-file", Path.Combine(dir.Root, "all.html"), "--side");
        Assert.True(layer.SideBySide);
    }

    [Fact]
    public void Side_flag_forces_side_by_side_alongside_export()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var layer = ParseArgs(dir.Root, "--export", Path.Combine(dir.Root, "out"), "--side");
        Assert.True(layer.SideBySide);
    }

    // --- suppression actually skips the in-place write, but still renders in memory ---

    [Fact]
    public void Suppressed_side_by_side_does_not_write_the_in_place_html()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        var item = RenderSingleFile(dir, "doc.md", sideBySide: false);
        Assert.False(File.Exists(Path.Combine(dir.Root, "doc.md.html")));
        Assert.NotNull(item.RenderedPage);
    }

    [Fact]
    public void Enabled_side_by_side_writes_the_in_place_html()
    {
        using var dir = new TempTree(("doc.md", "# Hi"));
        RenderSingleFile(dir, "doc.md", sideBySide: true);
        Assert.True(File.Exists(Path.Combine(dir.Root, "doc.md.html")));
    }

    // --- the full pipeline: --single-file + --export with no --side ---

    [Fact]
    public void Export_and_single_file_write_outputs_but_no_in_place_files()
    {
        using var dir = new TempTree(
            ("help/README.md", "# Readme\n\n[b](b.md)"),
            ("help/b.md", "# Bee"));
        var single = Path.Combine(dir.Root, "all.html");
        var outDir = Path.Combine(dir.Root, "out");

        RunCli(Path.Combine(dir.Root, "help"), "--single-file", single, "--export", outDir);

        // single file written
        Assert.True(File.Exists(single));
        // export dir has the rendered pages, from memory
        Assert.True(File.Exists(Path.Combine(outDir, "help", "README.md.html")));
        Assert.True(File.Exists(Path.Combine(outDir, "help", "b.md.html")));
        // no in-place side-by-side files next to the sources
        Assert.False(File.Exists(Path.Combine(dir.Root, "help", "README.md.html")));
        Assert.False(File.Exists(Path.Combine(dir.Root, "help", "b.md.html")));
    }

    // --- issue #4: file ordering and de-duplication for the assembled output ---

    [Fact]
    public void Explicit_files_keep_their_command_line_order()
    {
        using var dir = new TempTree(("a.md", "# a"), ("b.md", "# b"));
        var names = ParseItemNames(Path.Combine(dir.Root, "b.md"), Path.Combine(dir.Root, "a.md"));
        Assert.Equal(new[] { "b.md", "a.md" }, names);
