    [Fact]
    public void Readme_then_index_are_hoisted_to_the_front_of_a_directory()
    {
        using var dir = new TempTree(("d/zeta.md", "#"), ("d/alpha.md", "#"), ("d/README.md", "#"), ("d/Index.md", "#"));
        var names = ParseItemNames(Path.Combine(dir.Root, "d"));
